-- ============================================================================
-- Editorial blocks ανά προϊόν (slug: editorial/<product-slug>).
-- Το content είναι JSON — επεξεργάσιμο από το dashboard ως κείμενο σελίδας.
-- ============================================================================

insert into store.pages (slug, title, content, status) values
  ('editorial/samaraki-anesis', 'Άνεση σε κάθε βήμα.',
   '{"heading":"Άνεση σε κάθε βήμα.","body":"Το σαμαράκι άνεσης συνδυάζει μαλακή επένδυση και εργονομικό σχεδιασμό για καθημερινές βόλτες με στυλ και ασφάλεια. Ρυθμίζεται εύκολα για τέλεια εφαρμογή, ενώ το ανθεκτικό υλικό του προσφέρει άνεση και ελευθερία κίνησης σε κάθε σας εξόρμηση.","image":"products/samaraki-anesis/lifestyle.jpg","features":[{"icon":"leaf","label":"Μαλακή επένδυση"},{"icon":"sliders","label":"Ρυθμιζόμενη εφαρμογή"},{"icon":"clip","label":"Εύκολο κούμπωμα"}],"sections":[{"title":"Οδηγός μεγεθών","body":"XS: περίμετρος στήθους 28–38 cm — για πολύ μικρόσωμες φυλές.\nS: 38–48 cm — για μικρόσωμες φυλές.\nM: 48–60 cm — για μεσαίες φυλές.\nL: 60–74 cm — για μεγαλόσωμες φυλές.\nΜέτρησε την περίμετρο του στήθους στο πιο φαρδύ σημείο, πίσω από τα μπροστινά πόδια, και άφησε χώρο για δύο δάχτυλα."},{"title":"Φροντίδα & καθαρισμός","body":"Πλύσιμο στο χέρι με χλιαρό νερό και ήπιο σαπούνι. Στέγνωμα σε σκιερό μέρος, μακριά από άμεση θερμότητα. Μην χρησιμοποιείς λευκαντικό ή στεγνωτήριο."}]}',
   'published'),
  ('editorial/syntrivani-nerou', 'Φρέσκο νερό, όλη μέρα.',
   '{"heading":"Φρέσκο νερό, όλη μέρα.","body":"Η αθόρυβη αντλία κρατά το νερό σε συνεχή κίνηση και το φίλτρο άνθρακα κατακρατά τρίχες και υπολείμματα. Οι γάτες πίνουν φυσικά περισσότερο από τρεχούμενο νερό — μια μικρή αλλαγή με μεγάλη διαφορά στην καθημερινή τους ενυδάτωση.","image":"products/syntrivani-nerou/lifestyle.jpg","features":[{"icon":"drop","label":"Φίλτρο άνθρακα"},{"icon":"shield","label":"Αθόρυβη αντλία"},{"icon":"paw","label":"Χωρητικότητα 2L"}],"sections":[{"title":"Φροντίδα & καθαρισμός","body":"Καθάρισε τη δεξαμενή κάθε εβδομάδα με ζεστό νερό. Αντικατάστησε το φίλτρο κάθε 3–4 εβδομάδες για βέλτιστη απόδοση."}]}',
   'published')
on conflict (slug) do update set content = excluded.content, title = excluded.title, status = excluded.status;

-- Οδηγός μεγεθών ως δημόσια σελίδα (link από το PDP)
insert into store.pages (slug, title, content, status) values
  ('odigos-megethon', 'Οδηγός μεγεθών',
   E'## Πώς μετράω σωστά\n\nΜέτρησε την περίμετρο του στήθους στο πιο φαρδύ σημείο, ακριβώς πίσω από τα μπροστινά πόδια. Άφησε χώρο για δύο δάχτυλα ανάμεσα στον ιμάντα και το σώμα.\n\n| Μέγεθος | Περίμετρος στήθους |\n|---|---|\n| XS | 28–38 cm |\n| S | 38–48 cm |\n| M | 48–60 cm |\n| L | 60–74 cm |\n\nΑν το κατοικίδιό σου είναι ανάμεσα σε δύο μεγέθη, επίλεξε το μεγαλύτερο.',
   'published')
on conflict (slug) do update set content = excluded.content, status = excluded.status;

-- Σημείωση: οι εικόνες lifestyle των editorial blocks ζουν μόνο στο storage
-- (δεν καταχωρούνται στο store.product_images ώστε να μη μπουν στη gallery).
